    public FillMode Fill { get => Options.Fill; init => Options = Options with { Fill = value }; }
    public EaseType Ease { get => Options.Ease; init => Options = Options with { Ease = value }; }
    public Func<float, float>? EaseFunction { get => Options.EaseFunction; init => Options = Options with { EaseFunction = value }; }
    public Godot.Curve? Curve { get => Options.Curve; init => Options = Options with { Curve = value }; }
    public TweenProcessMode ProcessMode { get => Options.ProcessMode; init => Options = Options with { ProcessMode = value }; }
    public TweenPauseMode PauseMode { get => Options.PauseMode; init => Options = Options with { PauseMode = value }; }
    public bool SuppressCallbacksWhenTargetInvalid { get => Options.SuppressCallbacksWhenTargetInvalid; init => Options = Options with { SuppressCallbacksWhenTargetInvalid = value }; }

    public float? From { get; init; }
    public float? To { get; init; }
    public Action<TweenInstance<Godot.Control, float>>? OnAdd { get; init; }
    public Action<TweenInstance<Godot.Control, float>>? OnStart { get; init; }
    public Action<TweenInstance<Godot.Control, float>, float>? OnUpdate { get; init; }
    public Action<TweenInstance<Godot.Control, float>>? OnEnd { get; init; }
    public Action<TweenInstance<Godot.Control, float>>? OnCancel { get; init; }
    public Action<TweenInstance<Godot.Control, float>>? OnFinally { get; init; }

    TweenDefinition<Godot.Control, float> ITweenDefinition<Godot.Control, float>.CreatePlayback()
    {
        var playback = new tweens.gd.ControlOffsetBottomTween
        {
            From = From,
            To = To,
            OnAdd = OnAdd,
            OnStart = OnStart,
            OnUpdate = OnUpdate,
            OnEnd = OnEnd,
            OnCancel = OnCancel,
            OnFinally = OnFinally,
        };
        Options.CopyTo(playback);
        return playback;
    }
